00053 // Read a multibyte encoded uint64_t
00054 //
00055 uint64_t read_multibyte(BitstreamUnpacker &b, const std::string &l) {
00056     BitstreamUnpacker::ScopedContextLabel label(b, l);
00057 
00058     uint64_t result = 0;
00059     bool more = false;
00060     do {
00061         more = b.u(1, "mb-more") != 0;
00062         uint64_t bits = b.u(7, "mb-bits");
00063 
00064         result = (result << 7) | bits;
00065     } while (more);
00066 
00067     return result;
00068 }
00069 
00070 // Coded resolution
00071 //
00072 const unsigned resolution_table[51][2] = {
00073     {0, 0},       {360, 200},   {400, 240},   {480, 320},   {640, 360},   {640, 480},   {768, 480},   {800, 600},   {852, 480},
00074     {854, 480},   {856, 480},   {960, 540},   {960, 640},   {1024, 576},  {1024, 600},  {1024, 768},  {1152, 864},  {1280, 720},
00075     {1280, 800},  {1280, 1024}, {1360, 768},  {1366, 768},  {1440, 1050}, {1440, 900},  {1600, 1200}, {1680, 1050}, {1920, 1080},
00076     {1920, 1200}, {2048, 1080}, {2048, 1152}, {2048, 1536}, {2160, 1440}, {2560, 1440}, {2560, 1600}, {2560, 2048}, {3200, 1800},
00077     {3200, 2048}, {3200, 2400}, {3440, 1440}, {3840, 1600}, {3840, 2160}, {3840, 3072}, {4096, 2160}, {4096, 3072}, {5120, 2880},
00078     {5120, 3200}, {5120, 4096}, {6400, 4096}, {6400, 4800}, {7680, 4320}, {7680, 4800}};
00079 
00080 static_assert((sizeof(resolution_table) / sizeof(resolution_table[0])) == 51, "Resolution table is broken");
00081 
00082 } // namespace
