00084 Deserializer::Deserializer(const Packet &packet, SignaledConfiguration &dst_configuration,
00085                            Surface (&symbols)[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS])
00086     : Component("Deserializer"), view_(packet), b_(view_), dst_configuration_(dst_configuration), symbols_(symbols) {}
00087 
00088 // Top level of enhancement layer parsing
00089 //
00090 bool Deserializer::has_more() const { return !b_.empty(); };
00091 
00092 //
00093 //
00094 unsigned Deserializer::parse_block() {
00095 
00096     const unsigned payload_size_type = b_.u(3, "payload_size_type");
00097     const unsigned payload_type = b_.u(5, "payload_type");
00098 
00099     unsigned payload_byte_size = 0;
00100     switch (payload_size_type) {
00101     case 0:
00102         payload_byte_size = 0;
00103         break;
00104     case 1:
00105         payload_byte_size = 1;
00106         break;
00107     case 2:
00108         payload_byte_size = 2;
00109         break;
00110     case 3:
00111         payload_byte_size = 3;
00112         break;
00113     case 4:
00114         payload_byte_size = 4;
00115         break;
00116     case 5:
00117         payload_byte_size = 5;
00118         break;
00119     case 7:
00120         payload_byte_size = (unsigned)read_multibyte(b_, "payload_byte_size");
00121         break;
00122     default:
00123         CHECK(0);
00124         break;
00125     }
00126 
00127     // Read all payload into packet, then parse from that
00128     const Packet packet = b_.bytes(payload_byte_size);
00129     const PacketView view(packet);
00130     BitstreamUnpacker payload_bitstream(view);
00131 
00132     switch (payload_type) {
00133     case 0:
00134         parse_sequence_config(dst_configuration_.sequence_configuration, payload_bitstream);
00135         return SyntaxBlock_Sequence;
00136     case 1:
00137         parse_global_config(dst_configuration_.global_configuration, payload_bitstream);
00138         return SyntaxBlock_Global;
00139     case 2:
00140         parse_picture_config(dst_configuration_.picture_configuration, payload_bitstream,
00141                              dst_configuration_.global_configuration.num_residual_layers,
00142                              dst_configuration_.global_configuration.temporal_enabled);
00143         return SyntaxBlock_Picture;
00144     case 3:
00145         parse_encoded_data(dst_configuration_, payload_bitstream, dst_configuration_.global_configuration.num_processed_planes,
00146                            symbols_);
00147         return SyntaxBlock_EncodedData;
00148     case 4:
00149         parse_encoded_data_tiled(dst_configuration_, payload_bitstream,
00150                                  dst_configuration_.global_configuration.num_processed_planes, symbols_);
00151         return SyntaxBlock_EncodedData_Tiled;
00152     case 5:
00153         INFO("parse_additional_info");
00154         parse_additional_info(dst_configuration_.additional_info, payload_bitstream);
00155         return SyntaxBlock_Additional_Info;
00156     case 6:
00157         parse_filler(payload_bitstream);
00158         return SyntaxBlock_Filler;
00159     default:
00160         CHECK(0);
00161     }
00162 
00163     return 0;
00164 }
