00166 // Read each configuration
00167 //
00168 void Deserializer::parse_sequence_config(SequenceConfiguration &sequence_configuration, BitstreamUnpacker &b) {
00169 #if BITSTREAM_DEBUG
00170     fprintf(goBits, "@@@@ @@@@ sequence_config >>>> \n");
00171     fflush(goBits);
00172 #endif
00173 
00174     BitstreamUnpacker::ScopedContextLabel label(b, "sequence_config");
00175 
00176     const unsigned profile_idc = b.u(4, "profile_idc");
00177     sequence_configuration.level_idc = b.u(4, "level_idc");
00178     sequence_configuration.sublevel_idc = b.u(2, "sublevel_idc");
00179     sequence_configuration.conformance_window = b.u(1, "conformance_window_flag");
00180     b.u(5, "reserved");
00181     if (profile_idc == 15 || sequence_configuration.level_idc == 15) {
00182         const unsigned extended_profile_idc = b.u(3, "extended_profile_idc");
00183         const unsigned extended_level_idc = b.u(3, "extended_level_idc");
00184         b.u(1, "reserved");
00185     }
00186     if (sequence_configuration.conformance_window) {
00187         sequence_configuration.conf_win_left_offset = (unsigned)read_multibyte(b, "conf_win_left_offset");
00188         sequence_configuration.conf_win_right_offset = (unsigned)read_multibyte(b, "conf_win_right_offset");
00189         sequence_configuration.conf_win_top_offset = (unsigned)read_multibyte(b, "conf_win_top_offset");
00190         sequence_configuration.conf_win_bottom_offset = (unsigned)read_multibyte(b, "conf_win_bottom_offset");
00191     }
00192 
00193     switch (profile_idc) {
00194     case 0:
00195         sequence_configuration.profile_idc = Profile_Main;
00196         break;
00197     case 1:
00198         sequence_configuration.profile_idc = Profile_Main444;
00199         break;
00200     default:
00201         CHECK(0);
00202         break;
00203     }
00204 
00205 #if BITSTREAM_DEBUG
00206     fprintf(goBits, "@@@@ @@@@ sequence_config <<<< \n");
00207     fflush(goBits);
00208 #endif
00209 }
