00211 void Deserializer::parse_global_config(GlobalConfiguration &global_configuration, BitstreamUnpacker &b) {
00212 #if BITSTREAM_DEBUG
00213     fprintf(goBits, "@@@@ @@@@ global_config >>>> \n");
00214     fflush(goBits);
00215 #endif
00216 
00217     BitstreamUnpacker::ScopedContextLabel label(b, "global_config");
00218 
00219     const unsigned processed_planes_type = b.u(1, "processed_planes_type");
00220     const unsigned resolution_type = b.u(6, "resolution_type");
00221     const unsigned transform_type = b.u(1, "transform_type");
00222     const unsigned chroma_sampling_type = b.u(2, "chroma_sampling_type");
00223     const unsigned base_depth_type = b.u(2, "base_depth_type");
00224     const unsigned enhancement_depth_type = b.u(2, "enhancement_depth_type");
00225     const unsigned temporal_step_width_modifier_signalled = b.u(1, "temporal_step_width_modifier_signalled");
00226     global_configuration.predicted_residual_enabled = b.u(1, "predicted_residual_mode");
00227     global_configuration.temporal_tile_intra_signalling_enabled = b.u(1, "temporal_tile_intra_signalling_enabled");
00228     global_configuration.temporal_enabled = b.u(1, "temporal_enabled");
00229     const unsigned upsample_type = b.u(3, "upsample_type");
00230     const unsigned level_1_filtering_signalled = b.u(1, "level_1_filtering_signalled");
00231     const unsigned scaling_mode_level1 = b.u(2, "scaling_mode_level1");
00232     const unsigned scaling_mode_level2 = b.u(2, "scaling_mode_level2");
00233     const unsigned tile_dimensions_type = b.u(2, "tile_dimensions_type");
00234     const unsigned user_data_enabled = b.u(2, "user_data_enabled");
00235     switch (user_data_enabled) {
00236     case 0:
00237         global_configuration.user_data_enabled = UserData_None;
00238         break;
00239     case 1:
00240         global_configuration.user_data_enabled = UserData_2bits;
00241         break;
00242     case 2:
00243         global_configuration.user_data_enabled = UserData_6bits;
00244         break;
00245     default:
00246         CHECK(0);
00247         break;
00248     }
00249     global_configuration.level1_depth_flag = b.u(1, "level1_depth_flag");
00250 
00251     const unsigned chroma_step_width_flag = b.u(1, "chroma_step_width_flag");
00252 
00253     if (processed_planes_type == 0) {
00254         global_configuration.num_processed_planes = 1; // Y
00255     } else {
00256         const unsigned planes_type = b.u(4, "planes_type");
00257         b.u(4, "reserved");
00258         switch (planes_type) {
00259         case 1:
00260             global_configuration.num_processed_planes = 3; // YUV
00261             break;
00262         default:
00263             CHECK(0);
00264         }
00265     }
00266 
00267     if (temporal_step_width_modifier_signalled)
00268         global_configuration.temporal_step_width_modifier = b.u(8, "temporal_step_width_modifier");
00269     else
00270         global_configuration.temporal_step_width_modifier = 48;
00271 
00272     if (upsample_type == 4) {
00273         global_configuration.upsampling_coefficients[0] = b.u(16, "upsampling_coefficient[0]");
00274         global_configuration.upsampling_coefficients[1] = b.u(16, "upsampling_coefficient[1]");
00275         global_configuration.upsampling_coefficients[2] = b.u(16, "upsampling_coefficient[2]");
00276         global_configuration.upsampling_coefficients[3] = b.u(16, "upsampling_coefficient[3]");
00277     }
00278 
00279     if (level_1_filtering_signalled) {
00280         global_configuration.level_1_filtering_first_coefficient = b.u(4, "level_1_filtering_first_coefficient");
00281         global_configuration.level_1_filtering_second_coefficient = b.u(4, "level_1_filtering_second_coefficient");
00282     } else {
00283         global_configuration.level_1_filtering_first_coefficient = 0;
00284         global_configuration.level_1_filtering_second_coefficient = 0;
00285     }
00286 
00287     switch (tile_dimensions_type) {
00288     case 0:
00289         global_configuration.tile_dimensions_type = TileDimensions_None;
00290         global_configuration.tile_width = 0;
00291         global_configuration.tile_height = 0;
00292         break;
00293     case 1:
00294         global_configuration.tile_dimensions_type = TileDimensions_512x256;
00295         global_configuration.tile_width = 512;
00296         global_configuration.tile_height = 256;
00297         break;
00298     case 2:
00299         global_configuration.tile_dimensions_type = TileDimensions_1024x512;
00300         global_configuration.tile_width = 1024;
00301         global_configuration.tile_height = 512;
00302         break;
00303     case 3:
00304         global_configuration.tile_dimensions_type = TileDimensions_Custom;
00305         global_configuration.tile_width = b.u(16, "custom_tile_width");
00306         global_configuration.tile_height = b.u(16, "custom_tile_height");
00307         break;
00308     }
00309 
00310     if (tile_dimensions_type > 0) {
00311         b.u(5, "reserved");
00312         global_configuration.compression_type_entropy_enabled_per_tile = b.u(1, "compression_type_entropy_enabled_per_tile");
00313         const unsigned compression_type_size_per_tile = b.u(2, "compression_type_size_per_tile");
00314         switch (compression_type_size_per_tile) {
00315         case 0:
00316             global_configuration.compression_type_size_per_tile = CompressionType_None;
00317             break;
00318         case 1:
00319             global_configuration.compression_type_size_per_tile = CompressionType_Prefix;
00320             break;
00321         case 2:
00322             global_configuration.compression_type_size_per_tile = CompressionType_Prefix_OnDiff;
00323             break;
00324         default:
00325             CHECK(0);
00326             break;
00327         }
00328     }
00329 
00330     if (resolution_type > 0 && resolution_type < 51) {
00331         global_configuration.resolution_width = resolution_table[resolution_type][0];
00332         global_configuration.resolution_height = resolution_table[resolution_type][1];
00333     } else if (resolution_type == 63) {
00334         global_configuration.resolution_width = b.u(16, "resolution_width");
00335         global_configuration.resolution_height = b.u(16, "resolution_height");
00336     } else {
00337         CHECK(0);
00338     }
00339 
00340     if (chroma_step_width_flag == 1) {
00341         global_configuration.chroma_step_width_multiplier = b.u(8, "chroma_step_width_multiplier");
00342     } else {
00343         global_configuration.chroma_step_width_multiplier = 64;
00344     }
00345 
00346     switch (chroma_sampling_type) {
00347     case 0:
00348         global_configuration.colourspace = Colourspace_Y;
00349         global_configuration.num_image_planes = 1;
00350         CHECK(global_configuration.num_image_planes >= global_configuration.num_processed_planes);
00351         break;
00352     case 1:
00353         global_configuration.colourspace = Colourspace_YUV420;
00354         global_configuration.num_image_planes = 3;
00355         break;
00356     case 2:
00357         global_configuration.colourspace = Colourspace_YUV422;
00358         global_configuration.num_image_planes = 3;
00359         break;
00360     case 3:
00361         global_configuration.colourspace = Colourspace_YUV444;
00362         global_configuration.num_image_planes = 3;
00363         break;
00364     default:
00365         CHECK(0);
00366         break;
00367     }
00368 
00369     switch (transform_type) {
00370     case 0:
00371         global_configuration.transform_block_size = 2;
00372         global_configuration.num_residual_layers = 4;
00373         break;
00374     case 1:
00375         global_configuration.transform_block_size = 4;
00376         global_configuration.num_residual_layers = 16;
00377         break;
00378     default:
00379         CHECK(0);
00380         break;
00381     }
00382 
00383     switch (base_depth_type) {
00384     case 0:
00385         global_configuration.base_depth = 8;
00386         break;
00387     case 1:
00388         global_configuration.base_depth = 10;
00389         break;
00390     case 2:
00391         global_configuration.base_depth = 12;
00392         break;
00393     case 3:
00394         global_configuration.base_depth = 14;
00395         break;
00396     default:
00397         CHECK(0);
00398         break;
00399     }
00400 
00401     switch (enhancement_depth_type) {
00402     case 0:
00403         global_configuration.enhancement_depth = 8;
00404         switch (global_configuration.colourspace) {
00405         case Colourspace_Y:
00406             global_configuration.image_format = IMAGE_FORMAT_Y8;
00407             break;
00408         case Colourspace_YUV420:
00409             global_configuration.image_format = IMAGE_FORMAT_YUV420P8;
00410             break;
00411         case Colourspace_YUV422:
00412             global_configuration.image_format = IMAGE_FORMAT_YUV422P8;
00413             break;
00414         case Colourspace_YUV444:
00415             global_configuration.image_format = IMAGE_FORMAT_YUV444P8;
00416             break;
00417         default:
00418             CHECK(0);
00419             break;
00420         }
00421         break;
00422     case 1:
00423         global_configuration.enhancement_depth = 10;
00424         switch (global_configuration.colourspace) {
00425         case Colourspace_Y:
00426             global_configuration.image_format = IMAGE_FORMAT_Y10;
00427             break;
00428         case Colourspace_YUV420:
00429             global_configuration.image_format = IMAGE_FORMAT_YUV420P10;
00430             break;
00431         case Colourspace_YUV422:
00432             global_configuration.image_format = IMAGE_FORMAT_YUV422P10;
00433             break;
00434         case Colourspace_YUV444:
00435             global_configuration.image_format = IMAGE_FORMAT_YUV444P10;
00436             break;
00437         default:
00438             CHECK(0);
00439             break;
00440         }
00441         break;
00442     case 2:
00443         global_configuration.enhancement_depth = 12;
00444         switch (global_configuration.colourspace) {
00445         case Colourspace_Y:
00446             global_configuration.image_format = IMAGE_FORMAT_Y12;
00447             break;
00448         case Colourspace_YUV420:
00449             global_configuration.image_format = IMAGE_FORMAT_YUV420P12;
00450             break;
00451         case Colourspace_YUV422:
00452             global_configuration.image_format = IMAGE_FORMAT_YUV422P12;
00453             break;
00454         case Colourspace_YUV444:
00455             global_configuration.image_format = IMAGE_FORMAT_YUV444P12;
00456             break;
00457         default:
00458             CHECK(0);
00459             break;
00460         }
00461         break;
00462     case 3:
00463         global_configuration.enhancement_depth = 14;
00464         switch (global_configuration.colourspace) {
00465         case Colourspace_Y:
00466             global_configuration.image_format = IMAGE_FORMAT_Y14;
00467             break;
00468         case Colourspace_YUV420:
00469             global_configuration.image_format = IMAGE_FORMAT_YUV420P14;
00470             break;
00471         case Colourspace_YUV422:
00472             global_configuration.image_format = IMAGE_FORMAT_YUV422P14;
00473             break;
00474         case Colourspace_YUV444:
00475             global_configuration.image_format = IMAGE_FORMAT_YUV444P14;
00476             break;
00477         default:
00478             CHECK(0);
00479             break;
00480         }
00481         break;
00482     default:
00483         CHECK(0);
00484         break;
00485     }
00486 
00487     switch (upsample_type) {
00488     case 0:
00489         global_configuration.upsample = Upsample_Nearest;
00490         break;
00491     case 1:
00492         global_configuration.upsample = Upsample_Linear;
00493         break;
00494     case 2:
00495         global_configuration.upsample = Upsample_Cubic;
00496         break;
00497     case 3:
00498         global_configuration.upsample = Upsample_ModifiedCubic;
00499         break;
00500     case 4:
00501         global_configuration.upsample = Upsample_AdaptiveCubic;
00502         break;
00503     default:
00504         CHECK(0);
00505         break;
00506     }
00507 
00508     switch (scaling_mode_level1) {
00509     case 0:
00510         global_configuration.scaling_mode[LOQ_LEVEL_1] = ScalingMode_None;
00511         break;
00512     case 1:
00513         global_configuration.scaling_mode[LOQ_LEVEL_1] = ScalingMode_1D;
00514         break;
00515     case 2:
00516         global_configuration.scaling_mode[LOQ_LEVEL_1] = ScalingMode_2D;
00517         break;
00518     default:
00519         CHECK(0);
00520         break;
00521     }
00522 
00523     switch (scaling_mode_level2) {
00524     case 0:
00525         global_configuration.scaling_mode[LOQ_LEVEL_2] = ScalingMode_None;
00526         break;
00527     case 1:
00528         global_configuration.scaling_mode[LOQ_LEVEL_2] = ScalingMode_1D;
00529         break;
00530     case 2:
00531         global_configuration.scaling_mode[LOQ_LEVEL_2] = ScalingMode_2D;
00532         break;
00533     default:
00534         CHECK(0);
00535         break;
00536     }
00537 
00538 #if BITSTREAM_DEBUG
00539     fprintf(goBits, "@@@@ @@@@ global_config <<<< \n");
00540     fflush(goBits);
00541 #endif
00542 }
