00544 void Deserializer::parse_picture_config(PictureConfiguration &picture_configuration, BitstreamUnpacker &b,
00545                                         unsigned num_residual_layers, bool temporal_enabled) {
00546 #if BITSTREAM_DEBUG
00547     fprintf(goBits, "@@@@ @@@@ picture_config >>>> \n");
00548     fflush(goBits);
00549 #endif
00550 
00551     BitstreamUnpacker::ScopedContextLabel label(b, "picture_config");
00552     unsigned picture_type;
00553 
00554     picture_configuration.enhancement_enabled = !b.u(1, "no_enhancement_bit");
00555     if (picture_configuration.enhancement_enabled) {
00556         const unsigned quant_matrix_mode = b.u(3, "quant_matrix_mode");
00557         picture_configuration.dequant_offset_signalled = b.u(1, "dequant_offset_signalled");
00558         picture_type = b.u(1, "picture_type");
00559         picture_configuration.temporal_refresh = b.u(1, "temporal_refresh");
00560         if (temporal_enabled && !picture_configuration.temporal_refresh)
00561             picture_configuration.temporal_signalling_present = true;
00562         else
00563             picture_configuration.temporal_signalling_present = false;
00564         const unsigned step_width_level1_enabled = b.u(1, "step_width_level1_enabled");
00565         picture_configuration.step_width_loq[LOQ_LEVEL_2] = b.u(15, "step_width_level2");
00566         CHECK(picture_configuration.step_width_loq[LOQ_LEVEL_2] > 0);
00567         picture_configuration.dithering_control = b.u(1, "dithering_control");
00568 
00569         switch (quant_matrix_mode) {
00570         case 0:
00571             picture_configuration.quant_matrix_mode = QuantMatrix_BothPrevious;
00572             break;
00573         case 1:
00574             picture_configuration.quant_matrix_mode = QuantMatrix_BothDefault;
00575             break;
00576         case 2:
00577             picture_configuration.quant_matrix_mode = QuantMatrix_SameAndCustom;
00578             break;
00579         case 3:
00580             picture_configuration.quant_matrix_mode = QuantMatrix_Level2CustomLevel1Default;
00581             break;
00582         case 4:
00583             picture_configuration.quant_matrix_mode = QuantMatrix_Level2DefaultLevel1Custom;
00584             break;
00585         case 5:
00586             picture_configuration.quant_matrix_mode = QuantMatrix_DifferentAndCustom;
00587             break;
00588         default:
00589             CHECK(0);
00590             break;
00591         }
00592 
00593         if (picture_type) {
00594             const unsigned field_type = b.u(1, "field_type");
00595             switch (field_type) {
00596             case 0:
00597                 picture_configuration.field_type = FieldType_Top;
00598                 break;
00599             case 1:
00600                 picture_configuration.field_type = FieldType_Bottom;
00601                 break;
00602             default:
00603                 CHECK(0);
00604                 break;
00605             }
00606             b.u(7, "reserved");
00607         }
00608 
00609         if (step_width_level1_enabled) {
00610             picture_configuration.step_width_loq[LOQ_LEVEL_1] = b.u(15, "step_width_level1");
00611             CHECK(picture_configuration.step_width_loq[LOQ_LEVEL_1] > 0);
00612             picture_configuration.level_1_filtering_enabled = b.u(1, "level_1_filtering_enabled");
00613         } else
00614             picture_configuration.step_width_loq[LOQ_LEVEL_1] = MAX_STEP_WIDTH;
00615 
00616         if (picture_configuration.quant_matrix_mode == QuantMatrix_SameAndCustom ||
00617             picture_configuration.quant_matrix_mode == QuantMatrix_Level2CustomLevel1Default ||
00618             picture_configuration.quant_matrix_mode == QuantMatrix_DifferentAndCustom) {
00619             for (unsigned layerIndex = 0; layerIndex < num_residual_layers; layerIndex++)
00620                 picture_configuration.qm_coefficient_2[layerIndex] = b.u(8, "qm_coefficient_0");
00621         }
00622         if (picture_configuration.quant_matrix_mode == QuantMatrix_Level2DefaultLevel1Custom ||
00623             picture_configuration.quant_matrix_mode == QuantMatrix_DifferentAndCustom) {
00624             for (unsigned layerIndex = 0; layerIndex < num_residual_layers; layerIndex++)
00625                 picture_configuration.qm_coefficient_1[layerIndex] = b.u(8, "qm_coefficient_1");
00626         }
00627 
00628         if (picture_configuration.dequant_offset_signalled) {
00629             const unsigned dequant_offset_mode = b.u(1, "dequant_offset_mode");
00630             switch (dequant_offset_mode) {
00631             case 0:
00632                 picture_configuration.dequant_offset_mode = DequantOffset_Default;
00633                 break;
00634             case 1:
00635                 picture_configuration.dequant_offset_mode = DequantOffset_ConstOffset;
00636                 break;
00637             default:
00638                 CHECK(0);
00639                 break;
00640             }
00641             picture_configuration.dequant_offset = b.u(7, "dequant_offset");
00642         }
00643 
00644         if (picture_configuration.dithering_control) {
00645             const unsigned dithering_type = b.u(2, "dithering_type");
00646             switch (dithering_type) {
00647             case 0:
00648                 picture_configuration.dithering_type = Dithering_None;
00649                 break;
00650             case 1:
00651                 picture_configuration.dithering_type = Dithering_Uniform;
00652                 break;
00653             default:
00654                 CHECK(0);
00655                 break;
00656             }
00657             b.u(1, "reserved");
00658             if (picture_configuration.dithering_type != Dithering_None)
00659                 picture_configuration.dithering_strength = b.u(5, "dithering_strength");
00660             else
00661                 b.u(5, "reserved");
00662         }
00663     } else {
00664         b.u(4, "reserved");
00665         picture_type = b.u(1, "picture_type");
00666         picture_configuration.temporal_refresh = b.u(1, "temporal_refresh");
00667         picture_configuration.temporal_signalling_present = b.u(1, "temporal_signalling_present");
00668     }
00669 
00670     switch (picture_type) {
00671     case 0:
00672         picture_configuration.picture_type = PictureType_Frame;
00673         break;
00674     case 1:
00675         picture_configuration.picture_type = PictureType_Field;
00676         break;
00677     default:
00678         CHECK(0);
00679         break;
00680     }
00681 
00682 #if BITSTREAM_DEBUG
00683     fprintf(goBits, "@@@@ @@@@ picture_config <<<< \n");
00684     fflush(goBits);
00685 #endif
00686 }
00687 
00688 // Number of encoded layers in bitstream - residual + temporal
00689 static unsigned total_layers(const SignaledConfiguration &configuration, unsigned plane, unsigned loq) {
00690     return configuration.global_configuration.num_residual_layers +
00691            ((loq == LOQ_LEVEL_2 && configuration.picture_configuration.temporal_signalling_present) ? 1 : 0);
00692 }
00693 
00694 static unsigned first_layer(const SignaledConfiguration &configuration) {
00695     if (configuration.picture_configuration.enhancement_enabled)
00696         return 0;
00697     else
00698         // First layer is temporal
00699         return configuration.global_configuration.num_residual_layers;
00700 }
00701 
00702 static bool is_temporal_layer(const SignaledConfiguration &configuration, unsigned plane, unsigned loq, unsigned layer) {
00703     return layer == configuration.global_configuration.num_residual_layers;
00704 }
00705 
00706 void Deserializer::parse_encoded_data(SignaledConfiguration &dst_configuration, BitstreamUnpacker &b, unsigned num_planes,
00707                                       Surface symbols[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS]) {
00708 #if BITSTREAM_DEBUG
00709     fprintf(goBits, "@@@@ @@@@ encoded_data >>>> \n");
00710     fflush(goBits);
00711 #endif
00712     bool entropy_enabled[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS] = {false};
00713     bool rle_only[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS] = {false};
00714 
00715     for (unsigned plane = 0; plane < dst_configuration.global_configuration.num_processed_planes; ++plane) {
00716         for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00717             for (unsigned layer = first_layer(dst_configuration); layer < total_layers(dst_configuration, plane, loq); ++layer) {
00718                 BitstreamUnpacker::ScopedContextLabel label(b, "encoded_data");
00719                 entropy_enabled[plane][loq][layer] = b.u(1, "entropy_enabled");
00720                 rle_only[plane][loq][layer] = b.u(1, "rle_only");
00721             }
00722         }
00723     }
00724 
00725     // Byte alignment
00726 #if defined __OPT_MODULO__
00727     while ((b.bit_offset() & 0x07))
00728 #else
00729     while ((b.bit_offset() % 8 != 0))
00730 #endif
00731         CHECK(b.u(1, "alignment") == 0);
00732 
00733     for (unsigned plane = 0; plane < dst_configuration.global_configuration.num_processed_planes; ++plane) {
00734         if (dst_configuration.picture_configuration.enhancement_enabled ||
00735             dst_configuration.picture_configuration.temporal_signalling_present) {
00736             for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00737                 for (unsigned layer = first_layer(dst_configuration); layer < total_layers(dst_configuration, plane, loq);
00738                      ++layer) {
00739                     const SurfaceConfiguration &surface_configuration = dst_configuration.surface_configuration[plane][loq][layer];
00740                     Packet data;
00741 
00742                     if (entropy_enabled[plane][loq][layer]) {
00743                         BitstreamUnpacker::ScopedContextLabel label(b, format("surface[%d][%d][%d]", plane, loq, layer));
00744                         const uint64_t data_size = read_multibyte(b, "data_size");
00745                         CHECK(data_size < INT_MAX);
00746                         data = b.bytes((unsigned)data_size);
00747                     }
00748 
00749                     PacketView view(data);
00750                     BitstreamUnpacker pb(view);
00751                     if (!is_temporal_layer(dst_configuration, plane, loq, layer)) {
00752                         const bool use_tiled_encoding_order = dst_configuration.global_configuration.temporal_enabled ||
00753                                                               dst_configuration.global_configuration.tile_dimensions_type > 0;
00754                         if (use_tiled_encoding_order) {
00755                             symbols[plane][loq][layer] = EntropyDecoderResidualsTiled().process(
00756                                 surface_configuration.width, surface_configuration.height, entropy_enabled[plane][loq][layer],
00757                                 rle_only[plane][loq][layer], pb, dst_configuration.global_configuration.transform_block_size);
00758                         } else {
00759                             symbols[plane][loq][layer] = EntropyDecoderResiduals().process(
00760                                 surface_configuration.width, surface_configuration.height, entropy_enabled[plane][loq][layer],
00761                                 rle_only[plane][loq][layer], pb);
00762                         }
00763                     } else {
00764                         symbols[plane][loq][layer] = EntropyDecoderTemporal().process(
00765                             surface_configuration.width, surface_configuration.height, entropy_enabled[plane][loq][layer],
00766                             rle_only[plane][loq][layer], pb, dst_configuration.global_configuration.transform_block_size,
00767                             dst_configuration.global_configuration.temporal_tile_intra_signalling_enabled);
00768                     }
00769                 }
00770             }
00771         }
00772     }
00773 
00774 #if BITSTREAM_DEBUG
00775     fprintf(goBits, "@@@@ @@@@ encoded_data <<<< \n");
00776     fflush(goBits);
00777 #endif
00778 }
00779 
00780 static Surface decode_layer(const SignaledConfiguration &dst_configuration, unsigned plane, unsigned loq, unsigned layer,
00781                             unsigned width, unsigned height, bool entropy_enabled, bool rle_only, BitstreamUnpacker &b) {
00782 
00783     if (!is_temporal_layer(dst_configuration, plane, loq, layer)) {
00784         const bool use_tiled_encoding_order = dst_configuration.global_configuration.temporal_enabled ||
00785                                               dst_configuration.global_configuration.tile_dimensions_type > 0;
00786         if (use_tiled_encoding_order) {
00787             return EntropyDecoderResidualsTiled().process(width, height, entropy_enabled, rle_only, b,
00788                                                           dst_configuration.global_configuration.transform_block_size);
00789         } else {
00790             return EntropyDecoderResiduals().process(width, height, entropy_enabled, rle_only, b);
00791         }
00792 
00793     } else {
00794         return EntropyDecoderTemporal().process(width, height, entropy_enabled, rle_only, b,
00795                                                 dst_configuration.global_configuration.transform_block_size,
00796                                                 dst_configuration.global_configuration.temporal_tile_intra_signalling_enabled);
00797     }
00798 }
00799 
00800 static Surface assemble_layer(SignaledConfiguration &dst_configuration, unsigned plane, unsigned loq, unsigned layer,
00801                               unsigned width, unsigned height, unsigned tiles_x, unsigned tiles_y, unsigned tile_width,
00802                               unsigned tile_height, const std::vector<Surface> &tiles) {
00803 
00804     if (is_temporal_layer(dst_configuration, plane, layer, loq)) {
00805         std::vector<SurfaceView<uint8_t>> src;
00806         for (const auto &t : tiles)
00807             src.push_back(SurfaceView<uint8_t>(t));
00808 
00809         return Surface::build_from<uint8_t>()
00810             .generate(width, height,
00811                       [&](unsigned x, unsigned y) -> uint8_t {
00812                           const unsigned tx = x / tile_width;
00813                           const unsigned ty = y / tile_height;
00814                           CHECK(tx < tiles_x);
00815                           CHECK(ty < tiles_y);
00816                           return src[ty * tiles_x + tx].read(x % tile_width, y % tile_height);
00817                       })
00818             .finish();
00819     } else {
00820         std::vector<SurfaceView<int16_t>> src;
00821         for (const auto &t : tiles)
00822             src.push_back(SurfaceView<int16_t>(t));
00823 
00824         return Surface::build_from<int16_t>()
00825             .generate(width, height,
00826                       [&](unsigned x, unsigned y) -> int16_t {
00827                           const unsigned tx = x / tile_width;
00828                           const unsigned ty = y / tile_height;
00829                           CHECK(tx < tiles_x);
00830                           CHECK(ty < tiles_y);
00831                           return src[ty * tiles_x + tx].read(x % tile_width, y % tile_height);
00832                       })
00833             .finish();
00834     }
00835 }
00836 
00837 void Deserializer::parse_encoded_data_tiled(SignaledConfiguration &dst_configuration, BitstreamUnpacker &b, unsigned num_planes,
00838                                             Surface symbols[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS]) {
00839 
00840     CHECK(dst_configuration.global_configuration.tile_dimensions_type != TileDimensions_None);
00841 
00842     const unsigned transform_block_size = dst_configuration.global_configuration.transform_block_size;
00843     Dimensions dimensions;
00844     dimensions.set(dst_configuration, dst_configuration.global_configuration.resolution_width,
00845                    dst_configuration.global_configuration.resolution_height);
00846 
00847     // Per layer sizes
00848     struct {
00849         unsigned width;
00850         unsigned height;
00851         unsigned tile_width;
00852         unsigned tile_height;
00853         unsigned tiles_x;
00854         unsigned tiles_y;
00855         unsigned num_tiles;
00856     } sizes[MAX_NUM_PLANES][MAX_NUM_LOQS] = {0};
00857 
00858     unsigned total_tiles = 0;
00859 
00860     // Fill in layer sizes
00861     for (unsigned plane = 0; plane < dst_configuration.global_configuration.num_processed_planes; ++plane) {
00862         for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00863             const unsigned num_layers = total_layers(dst_configuration, plane, loq) - first_layer(dst_configuration);
00864 
00865             const unsigned tile_width = dimensions.tile_width(plane, loq);
00866             const unsigned tile_height = dimensions.tile_height(plane, loq);
00867 
00868             // Figure out tile breakdown for this level
00869             sizes[plane][loq].width = dimensions.layer_width(plane, loq);
00870             sizes[plane][loq].height = dimensions.layer_height(plane, loq);
00871             sizes[plane][loq].tile_width = tile_width;
00872             sizes[plane][loq].tile_height = tile_height;
00873             sizes[plane][loq].tiles_x = (sizes[plane][loq].width + tile_width - 1) / tile_width;
00874             sizes[plane][loq].tiles_y = (sizes[plane][loq].height + tile_height - 1) / tile_height;
00875             sizes[plane][loq].num_tiles = sizes[plane][loq].tiles_x * sizes[plane][loq].tiles_y;
00876 
00877             total_tiles += sizes[plane][loq].num_tiles * num_layers;
00878         }
00879     }
00880 
00881     // Parse per-layer rle_only flags
00882     bool rle_only[MAX_NUM_PLANES][MAX_NUM_LOQS][MAX_NUM_LAYERS] = {false};
00883 
00884     for (unsigned plane = 0; plane < dst_configuration.global_configuration.num_processed_planes; ++plane) {
00885         for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00886             if (dst_configuration.picture_configuration.enhancement_enabled) {
00887                 for (unsigned layer = first_layer(dst_configuration); layer < total_layers(dst_configuration, plane, loq);
00888                      ++layer) {
00889                     rle_only[plane][loq][layer] = b.u(1, "rle_only");
00890                 }
00891             }
00892         }
00893     }
00894 
00895     // Byte alignment
00896 #if defined __OPT_MODULO__
00897     while ((b.bit_offset() & 0x07))
00898 #else
00899     while ((b.bit_offset() % 8 != 0))
00900 #endif
00901         CHECK(b.u(1, "alignment") == 0);
00902 
00903     std::vector<bool> entropy_enabled(total_tiles, false);
00904 
00905     // Parse per tile entropy_enabled
00906     if (!dst_configuration.global_configuration.compression_type_entropy_enabled_per_tile) {
00907 
00908         int idx = 0;
00909         for (unsigned plane = 0; plane < dst_configuration.global_configuration.num_processed_planes; ++plane) {
00910             if (dst_configuration.picture_configuration.enhancement_enabled) {
00911                 for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00912                     for (unsigned layer = first_layer(dst_configuration); layer < total_layers(dst_configuration, plane, loq);
00913                          ++layer) {
00914                         for (unsigned tile = 0; tile < sizes[plane][loq].num_tiles; ++tile) {
00915                             entropy_enabled[idx] = b.u(1, "entropy_enabled");
00916                             idx++;
00917                         }
00918                     }
00919                 }
00920             }
00921         }
00922 
00923     } else {
00924         if (dst_configuration.picture_configuration.enhancement_enabled) {
00925             Surface ee = EntropyDecoderFlags().process(static_cast<unsigned>(entropy_enabled.size()), 1, b);
00926 
00927             const auto eeview = ee.view_as<uint8_t>();
00928             for (unsigned i = 0; i < entropy_enabled.size(); ++i)
00929                 entropy_enabled[i] = eeview.read(i, 0);
00930         }
00931     }
00932 
00933     // Byte alignment
00934 #if defined __OPT_MODULO__
00935     while ((b.bit_offset() & 0x07))
00936 #else
00937     while ((b.bit_offset() % 8 != 0))
00938 #endif
00939         CHECK(b.u(1, "alignment") == 0);
00940 
00941     if (dst_configuration.global_configuration.compression_type_size_per_tile == CompressionType::CompressionType_None) {
00942         // Uncompressed tile sizes and data
00943         int idx = 0;
00944         for (unsigned plane = 0; plane < dst_configuration.global_configuration.num_processed_planes; ++plane) {
00945             for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00946                 for (unsigned layer = first_layer(dst_configuration); layer < total_layers(dst_configuration, plane, loq);
00947                      ++layer) {
00948                     std::vector<Surface> tiles;
00949                     for (unsigned ty = 0; ty < sizes[plane][loq].tiles_y; ++ty) {
00950                         for (unsigned tx = 0; tx < sizes[plane][loq].tiles_x; ++tx) {
00951                             // Where is tile going to go?
00952                             const unsigned tx0 = tx * sizes[plane][loq].tile_width;
00953                             const unsigned ty0 = ty * sizes[plane][loq].tile_height;
00954                             // const unsigned tx1 = std::min((tx + 1) * tile_width, sizes[plane][loq].width);
00955                             const unsigned tx1 = LCEVC_MIN((tx + 1) * sizes[plane][loq].tile_width, sizes[plane][loq].width);
00956                             // const unsigned ty1 = std::min((ty + 1) * tile_height, sizes[plane][loq].height);
00957                             const unsigned ty1 = LCEVC_MIN((ty + 1) * sizes[plane][loq].tile_height, sizes[plane][loq].height);
00958 
00959                             Packet data;
00960                             if (entropy_enabled[idx]) {
00961                                 const uint64_t data_size = read_multibyte(b, "data_size");
00962                                 CHECK(data_size < INT_MAX);
00963                                 data = b.bytes((unsigned)data_size);
00964                             }
00965                             PacketView view(data);
00966                             BitstreamUnpacker pb(view);
00967                             tiles.push_back(decode_layer(dst_configuration, plane, loq, layer, tx1 - tx0, ty1 - ty0,
00968                                                          entropy_enabled[idx], rle_only[plane][loq][layer], pb));
00969                             idx++;
00970                         }
00971                     }
00972                     symbols[plane][loq][layer] =
00973                         assemble_layer(dst_configuration, plane, layer, loq, sizes[plane][loq].width, sizes[plane][loq].height,
00974                                        sizes[plane][loq].tiles_x, sizes[plane][loq].tiles_y, dimensions.tile_width(plane, loq),
00975                                        dimensions.tile_height(plane, loq), tiles);
00976                 }
00977             }
00978         }
00979     } else {
00980         int idx = 0;
00981         for (unsigned plane = 0; plane < dst_configuration.global_configuration.num_processed_planes; ++plane) {
00982             for (unsigned loq = 0; loq < MAX_NUM_LOQS; ++loq) {
00983                 for (unsigned layer = first_layer(dst_configuration); layer < total_layers(dst_configuration, plane, loq);
00984                      ++layer) {
00985 
00986                     // Does any tile contain data?
00987                     bool any_tile_enabled = false;
00988                     for (unsigned x = 0; x < sizes[plane][loq].num_tiles; x++) {
00989                         if (entropy_enabled[idx + x]) {
00990                             any_tile_enabled = true;
00991                             break;
00992                         }
00993                     }
00994 
00995                     Surface sz;
00996                     if (any_tile_enabled) {
00997                         // Decode sizes for this layer
00998                         sz = EntropyDecoderSizes().process(sizes[plane][loq].num_tiles, 1, b, entropy_enabled, idx,
00999                                                            dst_configuration.global_configuration.compression_type_size_per_tile);
01000                     } else {
01001                         sz = Surface::build_from<uint16_t>().fill(0, sizes[plane][loq].num_tiles, 1).finish();
01002                     }
01003                     // Byte alignment
01004 #if defined __OPT_MODULO__
01005                     while ((b.bit_offset() & 0x07))
01006 #else
01007                     while ((b.bit_offset() % 8 != 0))
01008 #endif
01009                         CHECK(b.u(1, "alignment") == 0);
01010 
01011                     const auto data_sizes = sz.view_as<uint16_t>();
01012 
01013                     std::vector<Surface> tiles;
01014 
01015                     for (unsigned ty = 0; ty < sizes[plane][loq].tiles_y; ++ty) {
01016                         for (unsigned tx = 0; tx < sizes[plane][loq].tiles_x; ++tx) {
01017                             // Where is tile going to go?
01018                             const unsigned tx0 = tx * sizes[plane][loq].tile_width;
01019                             const unsigned ty0 = ty * sizes[plane][loq].tile_height;
01020                             const unsigned tx1 = LCEVC_MIN((tx + 1) * sizes[plane][loq].tile_width, sizes[plane][loq].width);
01021                             const unsigned ty1 = LCEVC_MIN((ty + 1) * sizes[plane][loq].tile_height, sizes[plane][loq].height);
01022 
01023                             Packet data;
01024                             if (entropy_enabled[idx]) {
01025                                 const uint64_t data_size = data_sizes.read(ty * sizes[plane][loq].tiles_x + tx, 0);
01026                                 CHECK(data_size < INT_MAX && data_size > 0);
01027                                 data = b.bytes((unsigned)data_size);
01028                             }
01029                             PacketView view(data);
01030                             BitstreamUnpacker pb(view);
01031                             tiles.push_back(decode_layer(dst_configuration, plane, loq, layer, tx1 - tx0, ty1 - ty0,
01032                                                          entropy_enabled[idx], rle_only[plane][loq][layer], pb));
01033                             idx++;
01034                         }
01035                     }
01036 
01037                     symbols[plane][loq][layer] =
01038                         assemble_layer(dst_configuration, plane, layer, loq, sizes[plane][loq].width, sizes[plane][loq].height,
01039                                        sizes[plane][loq].tiles_x, sizes[plane][loq].tiles_y, dimensions.tile_width(plane, loq),
01040                                        dimensions.tile_height(plane, loq), tiles);
01041                 }
01042             }
01043         }
01044     }
01045 }
01046 
01047 void Deserializer::parse_additional_info(AdditionalInfo &additional_info, BitstreamUnpacker &b) {
01048     additional_info.additional_info_type = b.u(8, "additional_info_type");
01049     if (additional_info.additional_info_type == 0) {
01050         additional_info.payload_type = b.u(8, "payload_type");
01051         INFO("SeiPayload");
01052     } else if (additional_info.additional_info_type == 1) {
01053         INFO("VuiParameters");
01054     } else {
01055         // (additional_info.additional_info_type >= 2)
01056         CHECK(0);
01057     }
01058     // TODO
01059 }
01060 
01061 void Deserializer::parse_filler(BitstreamUnpacker &b) {
01062     BitstreamUnpacker::ScopedContextLabel label(b, "filler");
01063     // Check filler bytes are correct value
01064     while (!b.empty())
01065         CHECK(b.u(8, "filler") == 0xaa);
01066 }
